for (size_t i = 0; i < (size_t)(ZYDIS_REGISTER_MAX_VALUE + 1); ++i) {
    register_context->values[i] = 0;
}

// Seed a simple PRNG from one fuzzed 64-bit value to fill a bounded subset with non-trivial data
ZyanU64 v = *FUZZ_PARAM(ZyanU64);
size_t total = (size_t)(ZYDIS_REGISTER_MAX_VALUE + 1);
size_t to_fill = total < 128 ? total : 128; // bound the amount of work per call
for (size_t i = 0; i < to_fill; ++i) {
    // xorshift64* style mixing to vary content without multiple FUZZ_PARAM calls
    v ^= (v << 13);
    v ^= (v >> 7);
    v ^= (v << 17);
    register_context->values[i] = v;
}

// Mark initialized for downstream checks
FUZZ_SET_ATTR_INT(register_context, "initialized", 1);

/* Validation: Constructs a valid ZydisRegisterContext and seeds up to 128 registers with pseudo-random
 * values derived from a single fuzz seed (respecting FUZZ_PARAM loop limitations). Remaining entries
 * are zeroed. Object is ready for APIs requiring a register_context. */

