import random
from typing import List

# This generator produces valid x86/x64 instruction byte sequences that are likely to
# successfully decode across various Zydis machine modes. We focus on simple, widely
# supported encodings to maximize successful decodes for the provided fuzz stubs,
# which pass these bytes to ZydisDecoderDecodeFull / ZydisDisassemble*.
#
# Strategy:
# - Choose among a curated set of well-formed instructions with compact, valid opcodes.
# - Cover legacy, 0F-map, VEX/EVEX presence via common instructions where possible,
#   but primarily emphasize legacy encodings for maximum cross-mode validity.
# - Include a variety: NOPs, MOV reg/reg, MOV reg,imm, arithmetic ops, short branches
#   with valid relative displacements within the provided buffer range, calls/jmps,
#   segment-prefixed forms, REP-prefixed string ops, stack ops, RIP-relative LEA/MOV.
# - Keep length <= 64 bytes (well below the 4096-byte upper bound).
# - Ensure bytes are self-contained and do not rely on external memory.
#
# Notes:
# - The disassembler fuzzers cap the input length to small sizes; we therefore generate
#   a single instruction or a short sequence. Zydis decodes only the first instruction
#   from the buffer.
# - We avoid malformed or random bytes; all sequences are intended to be valid.

# Helper builders for common patterns

def rex(w: int = 0, r: int = 0, x: int = 0, b: int = 0) -> int:
    return 0x40 | ((w & 1) << 3) | ((r & 1) << 2) | ((x & 1) << 1) | (b & 1)

# Encode ModRM byte
# mod:2, reg:3, rm:3

def modrm(mod: int, reg: int, rm: int) -> int:
    return ((mod & 0x3) << 6) | ((reg & 0x7) << 3) | (rm & 0x7)

# Encode a short 8-bit relative displacement (for short jumps/branches)

def jcc_short(opcode: int, disp8: int) -> bytes:
    return bytes([opcode, disp8 & 0xFF])

# Common instruction encoders

def nop() -> bytes:
    return bytes([0x90])

def multi_nop(n: int) -> bytes:
    n = max(1, min(n, 15))
    # Use multi-byte NOP encodings from Intel manual; fallback to 0x90s
    patterns = {
        1: [0x90],
        2: [0x66, 0x90],
        3: [0x0F, 0x1F, 0x00],
        4: [0x0F, 0x1F, 0x40, 0x00],
        5: [0x0F, 0x1F, 0x44, 0x00, 0x00],
        6: [0x66, 0x0F, 0x1F, 0x44, 0x00, 0x00],
        7: [0x0F, 0x1F, 0x80, 0x00, 0x00, 0x00, 0x00],
        8: [0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        9: [0x66, 0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        10: [0x66, 0x66, 0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        11: [0x66, 0x66, 0x66, 0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        12: [0x66, 0x66, 0x66, 0x66, 0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        13: [0x66]*5 + [0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        14: [0x66]*6 + [0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
        15: [0x66]*7 + [0x0F, 0x1F, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00],
    }
    return bytes(patterns.get(n, [0x90]*n))

# MOV r64, imm64 or MOV r32, imm32 depending on operand size; we emit both variants

def mov_rax_imm64(val: int) -> bytes:
    imm = val & 0xFFFFFFFFFFFFFFFF
    return bytes([0x48, 0xB8]) + imm.to_bytes(8, 'little')  # REX.W + MOV r64, imm64 (RAX)

def mov_eax_imm32(val: int) -> bytes:
    imm = val & 0xFFFFFFFF
    return bytes([0xB8]) + imm.to_bytes(4, 'little')  # MOV EAX, imm32

# MOV r/m64, r64 with ModRM reg/reg (RAX,RAX)

def mov_rax_rax() -> bytes:
    return bytes([0x48, 0x89, modrm(0b11, 0, 0)])  # MOV [mod=11] r/m64 <- r64

# ADD/SUB/XOR reg, imm8 (AL/EAX/RAX variants)

def add_al_imm8(v: int) -> bytes:
    return bytes([0x04, v & 0xFF])

def add_eax_imm32(v: int) -> bytes:
    return bytes([0x05]) + (v & 0xFFFFFFFF).to_bytes(4, 'little')

def sub_eax_imm32(v: int) -> bytes:
    return bytes([0x2D]) + (v & 0xFFFFFFFF).to_bytes(4, 'little')

def xor_eax_imm32(v: int) -> bytes:
    return bytes([0x35]) + (v & 0xFFFFFFFF).to_bytes(4, 'little')

# Short branches (JMP short, Jcc short), ensure displacement within small buffer

def jmp_short(disp: int) -> bytes:
    return bytes([0xEB, disp & 0xFF])

def jz_short(disp: int) -> bytes:
    return jcc_short(0x74, disp)

def jnz_short(disp: int) -> bytes:
    return jcc_short(0x75, disp)

# CALL rel32, JMP rel32

def call_rel32(disp: int) -> bytes:
    return bytes([0xE8]) + (disp & 0xFFFFFFFF).to_bytes(4, 'little')

def jmp_rel32(disp: int) -> bytes:
    return bytes([0xE9]) + (disp & 0xFFFFFFFF).to_bytes(4, 'little')

# RET variants

def ret() -> bytes:
    return bytes([0xC3])

def ret_imm16(imm16: int) -> bytes:
    return bytes([0xC2, imm16 & 0xFF, (imm16 >> 8) & 0xFF])

# PUSH/POP

def push_rax() -> bytes:
    return bytes([0x50 | 0])  # PUSH RAX/EAX

def pop_rax() -> bytes:
    return bytes([0x58 | 0])  # POP RAX/EAX

# REP MOVSB (common string op with repeat prefix)

def rep_movsb() -> bytes:
    return bytes([0xF3, 0xA4])

# Segment override prefix with a simple MOV r/m, r form: FS: MOV [EAX], ECX (modrm with mem uses is safe as bytes)

def seg_override_fs_mov() -> bytes:
    return bytes([0x64, 0x89, modrm(0b00, 1, 0)])  # FS: MOV [EAX], ECX

# LEA reg, [rip+disp32] in 64-bit: 48 8D 05 disp32 -> LEA RAX, [RIP+disp32]

def lea_rax_riprel(disp32: int) -> bytes:
    return bytes([0x48, 0x8D, 0x05]) + (disp32 & 0xFFFFFFFF).to_bytes(4, 'little')

# Simple SSE instruction: XORPS XMM0, XMM0 (0F 57 C0)

def xorps_xmm0_xmm0() -> bytes:
    return bytes([0x0F, 0x57, 0xC0])

# VEX-encoded simple instruction (when supported by mode): VEX.NDS.LIG.0F.WIG 57 /r (XORPS) with XMM0,XMM0,XMM0
# Minimal 2-byte VEX for 0F map: C5 F8 57 C0

def vex_xorps_xmm0() -> bytes:
    return bytes([0xC5, 0xF8, 0x57, 0xC0])

# EVEX NOP-like safe instruction is tricky; instead emit an EVEX-prefixed XORPS equivalent for broader coverage
# EVEX.128 with zeroing/aa=0, simple reg-reg: 62 F1 7C 08 57 C0 (parameters chosen for XMM0/XMM0)

def evex_xorps_xmm0() -> bytes:
    return bytes([0x62, 0xF1, 0x7C, 0x08, 0x57, 0xC0])

# A small library of candidates

def candidates(rnd: random.Random) -> List[bytes]:
    vals8 = [0x00, 0x01, 0x7F, 0x80, 0xFF]
    vals16 = [0x0000, 0x0001, 0x7FFF, 0x8000, 0xFFFF]
    vals32 = [0, 1, 0x7FFFFFFF, 0x80000000, 0xFFFFFFFF]
    vals64 = [0, 1, 0x7FFFFFFFFFFFFFFF, 0x8000000000000000, 0xFFFFFFFFFFFFFFFF]

    seqs = []
    # Single-instruction forms
    seqs.append(nop())
    seqs.append(multi_nop(rnd.randint(2, 10)))
    seqs.append(mov_eax_imm32(rnd.choice(vals32)))
    seqs.append(mov_rax_imm64(rnd.choice(vals64)))
    seqs.append(mov_rax_rax())
    seqs.append(add_al_imm8(rnd.choice(vals8)))
    seqs.append(add_eax_imm32(rnd.choice(vals32)))
    seqs.append(sub_eax_imm32(rnd.choice(vals32)))
    seqs.append(xor_eax_imm32(rnd.choice(vals32)))
    seqs.append(push_rax())
    seqs.append(pop_rax())
    seqs.append(ret())
    seqs.append(ret_imm16(rnd.choice(vals16)))
    # Short branches with small displacements; decoder doesn't execute, so any disp is fine
    seqs.append(jmp_short(rnd.randint(-5, 5)))
    seqs.append(jz_short(rnd.randint(-5, 5)))
    seqs.append(jnz_short(rnd.randint(-5, 5)))
    # rel32 control transfers
    seqs.append(call_rel32(rnd.choice(vals32)))
    seqs.append(jmp_rel32(rnd.choice(vals32)))
    # REP MOVSB
    seqs.append(rep_movsb())
    # Segment override sample
    seqs.append(seg_override_fs_mov())
    # RIP-relative addressing and simple SSE/VEX/EVEX coverage
    seqs.append(lea_rax_riprel(rnd.choice(vals32)))
    seqs.append(xorps_xmm0_xmm0())
    seqs.append(vex_xorps_xmm0())
    seqs.append(evex_xorps_xmm0())

    # Two-instruction short sequences to provide more bytes (decoder takes first)
    seqs.append(mov_eax_imm32(rnd.choice(vals32)) + ret())
    seqs.append(push_rax() + pop_rax())
    seqs.append(multi_nop(rnd.randint(2, 5)) + xorps_xmm0_xmm0())

    return seqs


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    seqs = candidates(rnd)
    # Weight towards simple legacy encodings to maximize decode success across modes
    weights = [
        10, 6, 9, 5, 8, 7, 7, 6, 6, 6, 6, 5, 4,
        4, 4, 4, 5, 5, 6, 5, 7, 7, 3,
        8, 7, 6
    ]
    # Align weights length to seqs
    if len(weights) != len(seqs):
        # Fallback: equal weighting
        weights = [1] * len(seqs)

    choice = rnd.choices(seqs, weights=weights, k=1)[0]

    # The fuzz stubs may cap the read length; ensure we provide at least 1 byte and keep under 64
    buf = choice[:64]
    if len(buf) == 0:
        buf = nop()

    return bytes(buf)
